import React, { useState, useEffect } from "react";
import "./ViewTasks.css";
import Navbar from "../components/navbar";
import Footer from "../components/footer";
import StudentSidebar from "../components/StudentSidebar";
import axios from "axios";

const ViewTasks = () => {
  const [milestones, setMilestones] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [newMilestone, setNewMilestone] = useState({
    title: "",
    dueDate: "",
    status: "Pending"
  });
  const [newTask, setNewTask] = useState({
    title: "",
    status: "Pending"
  });
  const [studentData, setStudentData] = useState(null);
  const [groupData, setGroupData] = useState(null);
  const [loading, setLoading] = useState(true);

  const user = JSON.parse(localStorage.getItem("users"));

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);

        // 1. Fetch student data
        const studentResponse = await axios.get(
          `http://localhost:5000/api/student/user/${user.id}`
        );
        setStudentData(studentResponse.data);

        // 2. Fetch group data
        const groupResponse = await axios.post(
          `http://localhost:5000/api/group/student`,
          { regNo: studentResponse.data.regNo }
        );
        setGroupData(groupResponse.data);

        // 3. Fetch milestones for the group
        const milestoneResponse = await axios.get(
          `http://localhost:5000/api/milestone/group/${groupResponse.data.groupNo}`
        );
        setMilestones(milestoneResponse.data);

        // 4. Fetch all tasks for the group
        const taskResponse = await axios.get(
          `http://localhost:5000/api/task/group/${groupResponse.data.groupNo}`
        );
        setTasks(taskResponse.data);

      } catch (error) {
        console.error("Data fetching error:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [user.id]);

  // Group tasks by milestoneId
  const getTasksForMilestone = (milestoneId) => {
    return tasks.filter(task => task.milestoneId === milestoneId);
  };

  const handleAddMilestone = async () => {
    if (!newMilestone.title.trim()) {
      alert("Please enter a milestone title");
      return;
    }

    try {
      const milestoneData = {
        ...newMilestone,
        projectID: groupData.projectID
      };

      const response = await axios.post('http://localhost:5000/api/milestone', milestoneData);
      setMilestones([...milestones, response.data]);
      setNewMilestone({ title: "", dueDate: "", status: "Pending" });
    } catch (error) {
      console.error("Error adding milestone:", error);
    }
  };

  const handleAddTask = async (milestoneId) => {
    if (!newTask.title.trim()) {
      alert("Please enter a task title");
      return;
    }

    try {
      const taskData = {
        ...newTask,
        milestoneId,
        uploadedBy: studentData.regNo
      };

      const response = await axios.post('http://localhost:5000/api/task', taskData);
      setTasks([...tasks, response.data]);
      setNewTask({ title: "", status: "Pending" });
    } catch (error) {
      console.error("Error adding task:", error);
    }
  };

  const handleUpdateTaskStatus = async (taskId, newStatus) => {
    try {
      await axios.patch(`http://localhost:5000/api/task/${taskId}`, {
        status: newStatus,
        completedBy: studentData.regNo
      });

      // Update local state
      setTasks(tasks.map(task => 
        task._id === taskId ? { 
          ...task, 
          status: newStatus,
          completedBy: studentData.regNo 
        } : task
      ));
    } catch (error) {
      console.error("Error updating task:", error);
    }
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (!studentData) return <div>No student data found</div>;
  if (!studentData.isGrouped) return <div>Student is not part of any group yet</div>;

  return (
    <div className="tasks-container">
      <Navbar />
      <div className="content-wrapper">
        <StudentSidebar />
        <div className="main-content">
          <h1 className="tasks-title">Manage Milestones and Tasks</h1>
          <p className="group-info">Group: {groupData?.groupNo} | Project: {groupData?.projectID}</p>

          {/* Add Milestone Section */}
          <div className="milestone-section">
            <h2>Add New Milestone</h2>
            <input
              type="text"
              value={newMilestone.title}
              onChange={(e) => setNewMilestone({...newMilestone, title: e.target.value})}
              placeholder="Milestone title"
            />
            <input
              type="date"
              value={newMilestone.dueDate}
              onChange={(e) => setNewMilestone({...newMilestone, dueDate: e.target.value})}
            />
            <button onClick={handleAddMilestone}>Add Milestone</button>
          </div>

          {/* Milestones List */}
          <div className="milestone-list">
            {milestones.map((milestone) => (
              <div key={milestone._id} className="milestone-item">
                <h2>{milestone.title}</h2>
                <p>Due: {new Date(milestone.dueDate).toLocaleDateString()} | Status: {milestone.status}</p>

                {/* Add Task Section */}
                <div className="task-section">
                  <input
                    type="text"
                    value={newTask.title}
                    onChange={(e) => setNewTask({...newTask, title: e.target.value})}
                    placeholder="Task title"
                  />
                  <button onClick={() => handleAddTask(milestone._id)}>Add Task</button>
                </div>

                {/* Tasks Table */}
                <div className="tasks-table">
                  <table>
                    <thead>
                      <tr>
                        <th>Task</th>
                        <th>Status</th>
                        <th>Created By</th>
                        <th>Completed By</th>
                        <th>Actions</th>
                      </tr>
                    </thead>
                    <tbody>
                      {getTasksForMilestone(milestone._id).map((task) => (
                        <tr key={task._id}>
                          <td>{task.title}</td>
                          <td>{task.status}</td>
                          <td>{task.uploadedBy}</td>
                          <td>{task.completedBy || "N/A"}</td>
                          <td>
                            {task.status !== "Completed" && (
                              <button
                                onClick={() => handleUpdateTaskStatus(task._id, "Completed")}
                              >
                                Mark Complete
                              </button>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default ViewTasks;
